// Shared helpers for the GROUNDED NO MORE blueprint SVG generators.
// Every illustration in docs/assets/svg/ is generated by code in this folder:
// original linework, no OEM drawings, no traced imagery.
//
// Run:  node docs/assets/svg/src/build.mjs

export const C = {
  midnight: '#09131F',
  steel: '#132638',
  card: '#0F1E2E',
  paper: '#0B1826', // opaque fill for airframe surfaces (sits between midnight and card)
  teal: '#22C7B8',
  tealHi: '#7FF3E6',
  titanium: '#B9C8D6',
  amber: '#F5B942',
  copper: '#C47F52',
  red: '#E76B64',
  ice: '#F2F6FA',
  slate: '#6B7C8F',
};

export const FONT_MONO = "'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace";
export const FONT_DISPLAY = "'Space Grotesk', 'Inter', system-ui, sans-serif";

/** Round to 2 dp and drop trailing zeros so the SVG stays small and diff-friendly. */
export const n = (v) => {
  const r = Math.round(v * 100) / 100;
  return Object.is(r, -0) ? '0' : String(r);
};

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** Tiny element builder: el('rect', {x:1}, ...children) -> string. */
export function el(tag, attrs = {}, ...children) {
  const a = Object.entries(attrs)
    .filter(([, v]) => v !== undefined && v !== null && v !== false)
    .map(([k, v]) => ` ${k}="${typeof v === 'number' ? n(v) : esc(v)}"`)
    .join('');
  const kids = children.flat(Infinity).filter((c) => c !== undefined && c !== null && c !== false);
  return kids.length ? `<${tag}${a}>${kids.join('')}</${tag}>` : `<${tag}${a}/>`;
}
export const g = (attrs, ...kids) => el('g', attrs, ...kids);
export const path = (d, cls, extra = {}) => el('path', { d, class: cls, ...extra });
export const text = (x, y, s, cls, extra = {}) => el('text', { x, y, class: cls, ...extra }, esc(s));

/** Polyline path from [[x,y],...] */
export const poly = (pts, close = false) =>
  'M' + pts.map(([x, y]) => `${n(x)},${n(y)}`).join('L') + (close ? 'Z' : '');

