/** Common <defs>: glow filter, arrowheads, grid pattern. */
export function baseDefs({ gridMinor = 20, gridMajor = 100 } = {}) {
  return el(
    'defs',
    {},
    el(
      'filter',
      { id: 'bp-glow', x: '-30%', y: '-30%', width: '160%', height: '160%' },
      el('feGaussianBlur', { in: 'SourceGraphic', stdDeviation: 2.4, result: 'b' }),
      el('feMerge', {}, el('feMergeNode', { in: 'b' }), el('feMergeNode', { in: 'SourceGraphic' }))
    ),
    el(
      'marker',
      { id: 'bp-arr', viewBox: '0 0 10 10', refX: 10, refY: 5, markerWidth: 9, markerHeight: 9, orient: 'auto-start-reverse', markerUnits: 'userSpaceOnUse' },
      el('path', { d: 'M0,2.6L10,5L0,7.4Z', class: 'bp-arrow' })
    ),
    el(
      'marker',
      { id: 'bp-arr-teal', viewBox: '0 0 10 10', refX: 9, refY: 5, markerWidth: 10, markerHeight: 10, orient: 'auto-start-reverse', markerUnits: 'userSpaceOnUse' },
      el('path', { d: 'M0,1.5L10,5L0,8.5L2.5,5Z', fill: C.teal })
    ),
    el(
      'pattern',
      { id: 'bp-grid', width: gridMajor, height: gridMajor, patternUnits: 'userSpaceOnUse' },
      ...Array.from({ length: gridMajor / gridMinor }, (_, i) =>
        el('path', { d: `M${i * gridMinor},0V${gridMajor}M0,${i * gridMinor}H${gridMajor}`, class: 'bp-grid-minor' })
      ),
      el('path', { d: `M0,0V${gridMajor}M0,0H${gridMajor}`, class: 'bp-grid-major' })
    )
  );
}

export function svgDoc({ w, h, title, desc, body, extraStyle = '', attrs = {}, defs = '' }) {
  return (
    `<?xml version="1.0" encoding="UTF-8"?>\n` +
    `<!-- Generated by docs/assets/svg/src/build.mjs — original schematic artwork for GROUNDED NO MORE. Not an OEM drawing; not engineering data. -->\n` +
    el(
      'svg',
      { xmlns: 'http://www.w3.org/2000/svg', viewBox: `0 0 ${w} ${h}`, width: w, height: h, role: 'img', 'aria-labelledby': 'bp-title bp-desc', fill: 'none', ...attrs },
      el('title', { id: 'bp-title' }, esc(title)),
      el('desc', { id: 'bp-desc' }, esc(desc)),
      baseStyle(extraStyle),
      baseDefs(),
      defs,
      body
    ) +
    '\n'
  );
}

/** Dimension line with arrowheads and centred label (horizontal or vertical). */
export function dimension({ x1, y1, x2, y2, label, ext = [], vertical = false, at = 0.5 }) {
  const mx = x1 + (x2 - x1) * at;
  const my = y1 + (y2 - y1) * at;
  const parts = [];
  ext.forEach((e) => parts.push(path(poly(e), 'bp-ext')));
  const gap = label.length * 9 + 24;
  if (!vertical) {
    parts.push(path(`M${n(x1)},${n(y1)}H${n(mx - gap / 2)}`, 'bp-dim', { 'marker-start': 'url(#bp-arr)' }));
    parts.push(path(`M${n(mx + gap / 2)},${n(y1)}H${n(x2)}`, 'bp-dim', { 'marker-end': 'url(#bp-arr)' }));
    parts.push(text(mx, y1 + 4, label, 'bp-t-dim', { 'text-anchor': 'middle' }));
  } else {
    parts.push(path(`M${n(x1)},${n(y1)}V${n(my - gap / 2)}`, 'bp-dim', { 'marker-start': 'url(#bp-arr)' }));
    parts.push(path(`M${n(x1)},${n(my + gap / 2)}V${n(y2)}`, 'bp-dim', { 'marker-end': 'url(#bp-arr)' }));
    parts.push(text(x1, my + 4, label, 'bp-t-dim', { 'text-anchor': 'middle', transform: `rotate(-90 ${n(x1)} ${n(my + 4)})` }));
  }
  return g({ class: 'bp-dim-g' }, parts);
}

/** Drawing title block. */
export function titleBlock({ x, y, w = 300, title = 'GENERIC TWIN-ENGINE AIRLINER', sheet = '01', rev = 'A', scale = 'NTS' }) {
  const h = 116;
  const r1 = 40, r2 = 26, r3 = 26;
  const c = w / 3;
  return g(
    { class: 'bp-tblock' },
    el('rect', { x, y, width: w, height: h, class: 'bp-tb' }),
    el('line', { x1: x, y1: y + r1, x2: x + w, y2: y + r1, class: 'bp-tb-rule' }),
    el('line', { x1: x, y1: y + r1 + r2, x2: x + w, y2: y + r1 + r2, class: 'bp-tb-rule' }),
    el('line', { x1: x, y1: y + r1 + r2 + r3, x2: x + w, y2: y + r1 + r2 + r3, class: 'bp-tb-rule' }),
    el('line', { x1: x + c, y1: y + r1 + r2, x2: x + c, y2: y + r1 + r2 + r3, class: 'bp-tb-rule' }),
    el('line', { x1: x + 2 * c, y1: y + r1 + r2, x2: x + 2 * c, y2: y + r1 + r2 + r3, class: 'bp-tb-rule' }),
    text(x + 10, y + 13, 'PROJECT', 'bp-t-xs'),
    text(x + 10, y + 32, 'GROUNDED NO MORE', 'bp-t-title'),
    text(x + 10, y + r1 + 17, title, 'bp-t-sm'),
    text(x + 10, y + r1 + r2 + 17, `SHEET ${sheet}`, 'bp-t-sm'),
    text(x + c + 10, y + r1 + r2 + 17, `REV ${rev}`, 'bp-t-sm'),
    text(x + 2 * c + 10, y + r1 + r2 + 17, `SCALE ${scale}`, 'bp-t-sm'),
    text(x + 10, y + r1 + r2 + r3 + 16, 'SCHEMATIC — NOT ENGINEERING DATA', 'bp-t-warn')
  );
}

/** Drawing sheet frame with zone ticks (A.. / 1..). */
export function sheetFrame(w, h, { inset = 12, zonesX = 8, zonesY = 5 } = {}) {
  const parts = [
    el('rect', { x: inset, y: inset, width: w - 2 * inset, height: h - 2 * inset, class: 'bp-frame', rx: 2 }),
    el('rect', { x: inset + 14, y: inset + 14, width: w - 2 * inset - 28, height: h - 2 * inset - 28, class: 'bp-frame-thin' }),
  ];
  const letters = 'ABCDEFGHJK';
  for (let i = 0; i <= zonesX; i++) {
    const x = inset + 14 + (i * (w - 2 * inset - 28)) / zonesX;
    if (i > 0 && i < zonesX) {
      parts.push(el('line', { x1: x, y1: inset, x2: x, y2: inset + 14, class: 'bp-frame-thin' }));
      parts.push(el('line', { x1: x, y1: h - inset - 14, x2: x, y2: h - inset, class: 'bp-frame-thin' }));
    }
    if (i < zonesX) {
      const cx = x + (w - 2 * inset - 28) / zonesX / 2;
      parts.push(text(cx, inset + 10.5, String(zonesX - i), 'bp-t-xs', { 'text-anchor': 'middle' }));
      parts.push(text(cx, h - inset - 3.5, String(zonesX - i), 'bp-t-xs', { 'text-anchor': 'middle' }));
    }
  }
  for (let j = 0; j <= zonesY; j++) {
    const y = inset + 14 + (j * (h - 2 * inset - 28)) / zonesY;
    if (j > 0 && j < zonesY) {
      parts.push(el('line', { x1: inset, y1: y, x2: inset + 14, y2: y, class: 'bp-frame-thin' }));
      parts.push(el('line', { x1: w - inset - 14, y1: y, x2: w - inset, y2: y, class: 'bp-frame-thin' }));
    }
    if (j < zonesY) {
      const cy = y + (h - 2 * inset - 28) / zonesY / 2 + 3.5;
      parts.push(text(inset + 7, cy, letters[j], 'bp-t-xs', { 'text-anchor': 'middle' }));
      parts.push(text(w - inset - 7, cy, letters[j], 'bp-t-xs', { 'text-anchor': 'middle' }));
    }
  }
  return g({ class: 'bp-frameset' }, parts);
}

// ---------- isometric primitives (used by the exploded diagrams) ----------
const COS30 = Math.cos(Math.PI / 6);
const SIN30 = 0.5;
/** Project a 3-D point (x right-down, y left-down, z up) to 2-D isometric. */
export const iso = ([x, y, z], s = 1, o = [0, 0]) => [o[0] + (x - y) * COS30 * s, o[1] + ((x + y) * SIN30 - z) * s];

/** Isometric box: three visible faces (top, +x face, +y face). */
export function isoBox(o, [x, y, z], [w, d, h], s, cls = 'bp-iso') {
  const P = (a, b, c) => iso([x + a, y + b, z + c], s, o);
  const top = [P(0, 0, h), P(w, 0, h), P(w, d, h), P(0, d, h)];
  const right = [P(w, 0, 0), P(w, d, 0), P(w, d, h), P(w, 0, h)]; // +x face
  const left = [P(0, d, 0), P(w, d, 0), P(w, d, h), P(0, d, h)]; // +y face
  return g(
    { class: cls },
    path(poly(right, true), 'bp-face-r'),
    path(poly(left, true), 'bp-face-l'),
    path(poly(top, true), 'bp-face-t')
  );
}

/** Points of a 3-D circle (centre c, unit axis a, radius r), projected. */
function circle3(c, a, r, s, o, steps = 48) {
  // pick two vectors orthogonal to a
  const ref = Math.abs(a[2]) < 0.9 ? [0, 0, 1] : [1, 0, 0];
  const cross = (u, v) => [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
  const norm = (u) => { const l = Math.hypot(...u); return u.map((q) => q / l); };
  const u = norm(cross(a, ref));
  const v = norm(cross(a, u));
  const pts = [];
  for (let i = 0; i < steps; i++) {
    const t = (i / steps) * Math.PI * 2;
    pts.push(iso([c[0] + r * (Math.cos(t) * u[0] + Math.sin(t) * v[0]), c[1] + r * (Math.cos(t) * u[1] + Math.sin(t) * v[1]), c[2] + r * (Math.cos(t) * u[2] + Math.sin(t) * v[2])], s, o));
  }
  return pts;
}

function hull(points) {
  const p = points.slice().sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const cr = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lo = [];
  for (const q of p) { while (lo.length >= 2 && cr(lo[lo.length - 2], lo[lo.length - 1], q) <= 0) lo.pop(); lo.push(q); }
  const up = [];
  for (const q of p.reverse()) { while (up.length >= 2 && cr(up[up.length - 2], up[up.length - 1], q) <= 0) up.pop(); up.push(q); }
  return lo.slice(0, -1).concat(up.slice(0, -1));
}

/**
 * Isometric cylinder from centre c along unit axis a, length len, radius r.
 * Draws the silhouette (hull), the visible end cap and optional ring lines at fractions.
 */
export function isoCyl(o, c, a, r, len, s, { rings = [], cls = 'bp-iso', capInner = 0 } = {}) {
  const c2 = [c[0] + a[0] * len, c[1] + a[1] * len, c[2] + a[2] * len];
  const e1 = circle3(c, a, r, s, o);
  const e2 = circle3(c2, a, r, s, o);
  const vis = a[0] + a[1] + a[2] > 0 ? e2 : e1; // the cap facing the viewer (+1,+1,+1)
  const parts = [path(poly(hull(e1.concat(e2)), true), 'bp-face-l'), path(poly(vis, true), 'bp-face-t')];
  if (capInner) {
    const cc = a[0] + a[1] + a[2] > 0 ? c2 : c;
    parts.push(path(poly(circle3(cc, a, r * capInner, s, o), true), 'bp-detail'));
  }
  rings.forEach((f) => {
    const cc = [c[0] + a[0] * len * f, c[1] + a[1] * len * f, c[2] + a[2] * len * f];
    const pts = circle3(cc, a, r, s, o, 48);
    // only the front half of the ring is visible: keep points whose depth faces the viewer
    parts.push(path(poly(frontHalf(pts, cc, a, r, s, o)), 'bp-detail'));
  });
  return g({ class: cls }, parts);
}

function frontHalf(pts) {
  // Approximation: the visible half of a ring is the half with the larger screen-y (lower on screen) for
  // vertical axes, which reads correctly for the stylised diagrams used here.
  const cy = pts.reduce((m, p) => m + p[1], 0) / pts.length;
  const out = [];
  let started = false;
  const k = pts.findIndex((p, i) => p[1] >= cy && pts[(i - 1 + pts.length) % pts.length][1] < cy);
  const start = k < 0 ? 0 : k;
  for (let i = 0; i < pts.length; i++) {
    const p = pts[(start + i) % pts.length];
    if (p[1] >= cy - 0.01) { out.push(p); started = true; } else if (started) break;
  }
  return out.length > 1 ? out : pts;
}

export const isoPoint = iso;
